  /* settings controls: language changes instantly (no reload); currency and decimals re-render in place */
  function saveOrg(field, value) {
    try { var o = org(); o[field] = value; LS.setItem('orgInfo', JSON.stringify(o)); } catch (e) {}
  }
  document.addEventListener('change', function (e) {
    var t = e.target; if (!t || !t.id) return;
    if (t.id === 'language') { LS.setItem('appLanguage', t.value); saveOrg('language', t.value); setLang(t.value, { force: true }); }
    else if (t.id === 'baseCurrency') { LS.setItem('appBaseCurrency', t.value); saveOrg('baseCurrency', t.value); setTimeout(function () { ratesChanged(); paintRatesCard(); }, 30); }
    else if (t.id === 'decimalPlaces') { LS.setItem('appDecimalPlaces', t.value); saveOrg('decimalPlaces', t.value); setTimeout(ratesChanged, 30); }
  });

  /* ============================================================ rates card (Settings) */
  function paintRatesCard() {
    var c = document.getElementById('acxRatesCard'); if (!c) return;
    var l = J(KEYS.live, null), t = tables(), nm = Object.keys(t.manual).length, b = baseCur();
    var info = c.querySelector('#acxRatesInfo'), cb = c.querySelector('#acxUseLive');
    if (cb) cb.checked = LS.getItem(KEYS.useLive) !== '0';
    var when = l && l.t ? new Date(l.t).toLocaleString() : 'never';
    var line = '1 ' + (b === 'KES' ? 'USD' : b) + ' = ' + fmtNum(b === 'KES' ? kesPer('USD') : kesPer(b)) + ' KES (' + rateSource(b === 'KES' ? 'USD' : b) + ')';
    if (info) info.textContent = 'Live rates last updated: ' + when + '. Manual rates: ' + nm + '. ' + line + '.';
  }
