    c.style.cssText = 'grid-column:1/-1;font-size:12px;color:#475569;border:1px solid #e2e8f0;background:#f8fafc;border-radius:6px;padding:8px 10px;display:flex;flex-wrap:wrap;gap:10px;align-items:center';
    c.innerHTML = '<b>Exchange rates</b><label style="display:flex;gap:4px;align-items:center"><input type="checkbox" id="acxUseLive"> Use live rates</label>' +
      '<button type="button" id="acxUpdateRates" style="border:1px solid #1e3a8a;color:#1e3a8a;border-radius:4px;padding:2px 8px">Update now</button><span id="acxRatesInfo"></span>' +
      '<span style="flex-basis:100%">A rate you enter manually always wins over the live rate.</span>';
