    c.querySelector('#acxUpdateRates').addEventListener('click', function () {
      var b = this; b.disabled = true; b.textContent = 'Updating...';
      LS.setItem(KEYS.useLive, '1');
      refreshLive(true).then(function (ok) { b.disabled = false; b.textContent = ok ? 'Updated' : 'Could not reach rate service'; setTimeout(function () { b.textContent = 'Update now'; }, 2500); });
    });
